139	            missingFields.add("firstName");
140	        }
141	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
142	            missingFields.add("lastName");
143	        }
144	        // Normalize the address up front; the required-field check rejects it when it is blank
145	        // after normalization (e.g. a whitespace-only value collapses to the empty string).
146	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
147	        if (!StringUtils.hasText(normalizedAddress)) {
148	            missingFields.add("address");
149	        }
150	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
151	            missingFields.add("city");
152	        }
153	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
154	            missingFields.add("telephone");
155	        }
156	        if (!missingFields.isEmpty()) {
157	            throw new InvalidRequestException(missingFields);
158	        }
159	        HttpHeaders headers = new HttpHeaders();
160	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
161	        // Store (and later return) the normalized address computed above.
162	        owner.setAddress(normalizedAddress);
163	        // Normalize the telephone into E.164 form (reject with 400 when it cannot form a valid one).
164	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
165	        owner.setTelephone(normalizedTelephone);
166	        // Normalize the (optional) email: reject a syntactically invalid address, otherwise store it lower-cased.
167	        owner.setEmail(normalizeEmail(owner.getEmail()));
168	        // Default the (optional) registration date to the server's current date when none was supplied.
169	        if (owner.getRegistrationDate() == null) {
170	            owner.setRegistrationDate(LocalDate.now());
171	        }
172	        // Reject the request if the E.164 telephone is already used by another owner.
173	        if (!this.clinicService.findOwnerByTelephone(normalizedTelephone).isEmpty()) {
174	            throw new DuplicateTelephoneException(normalizedTelephone);
175	        }
176	        // Reject the request if another owner already shares the same last name and address
177	        // (compared case-insensitively with collapsed whitespace), unless the caller opts in
178	        // by setting 'sharesHousehold' true. When they do opt in and an existing household is
179	        // matched, assign a stable shared 'householdId' to the new owner and backfill it onto
180	        // every existing member that does not yet carry it.
181	        List<Owner> householdMembers = findHouseholdMembers(owner.getLastName(), owner.getAddress());
182	        if (!householdMembers.isEmpty()) {
183	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
184	                throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
185	            }
186	            String householdId = generateHouseholdId(owner.getLastName(), owner.getAddress());
187	            owner.setHouseholdId(householdId);
188	            for (Owner member : householdMembers) {
189	                if (!householdId.equals(member.getHouseholdId())) {
190	                    member.setHouseholdId(householdId);
191	                    this.clinicService.saveOwner(member);
192	                }
193	            }
194	        }
195	        // Record how many existing owners already share this first name and last name
196	        // (compared case-insensitively) before this owner is created.
197	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
198	        // Assign the customer code '<LAST3>-<NNNN>' before persisting.
199	        owner.setCustomerCode(generateCustomerCode(owner.getLastName()));
200	        // Assign the membership number '<customerCode>-M<YY>' where YY is the last two
201	        // digits of the registration date year (e.g. 'SMI-0007-M26').
202	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
203	        this.clinicService.saveOwner(owner);
204	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
205	        headers.setLocation(UriComponentsBuilder.newInstance()
206	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
207	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
208	    }
209	
210	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
211	    @Override
212	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
213	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
214	        if (currentOwner == null) {
215	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
216	        }
217	        currentOwner.setAddress(ownerFieldsDto.getAddress());
218	        currentOwner.setCity(ownerFieldsDto.getCity());
219	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
220	        currentOwner.setLastName(ownerFieldsDto.getLastName());
221	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
222	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
223	        this.clinicService.saveOwner(currentOwner);
224	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
225	    }
226	
227	    /**
228	     * Generate a customer code formatted {@code <LAST3>-<NNNN>}, where {@code LAST3} is the
229	     * upper-cased first three letters of {@code lastName} and {@code NNNN} is a global 4-digit
230	     * zero-padded sequence equal to one more than the current number of owners (e.g. {@code SMI-0007}).
231	     *
232	     * @param lastName the owner's last name
233	     * @return the generated customer code
234	     */
235	    private String generateCustomerCode(String lastName) {
236	        String prefix = lastName.length() >= 3 ? lastName.substring(0, 3) : lastName;
237	        int sequence = this.clinicService.findAllOwners().size() + 1;
238	        return String.format("%s-%04d", prefix.toUpperCase(Locale.ROOT), sequence);
239	    }
240	
241	    /**
242	     * Generate a membership number formatted {@code <customerCode>-M<YY>}, where {@code YY} is the
243	     * last two digits of the {@code registrationDate} year (e.g. {@code SMI-0007-M26}).
244	     *
245	     * @param customerCode     the owner's already-assigned customer code
246	     * @param registrationDate the owner's registration date
247	     * @return the generated membership number
248	     */
249	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
250	        String yy = String.format("%02d", registrationDate.getYear() % 100);
251	        return String.format("%s-M%s", customerCode, yy);
252	    }
253	
254	    /**
255	     * Count the existing owners that share the given first name and last name, comparing each
256	     * case-insensitively (trimmed, with internal whitespace collapsed). The incoming owner is not
257	     * yet persisted, so it is not included in the count.
258	     *
259	     * @param firstName the incoming owner's first name
260	     * @param lastName  the incoming owner's last name
261	     * @return the number of existing namesakes
262	     */
263	    private int countNamesakes(String firstName, String lastName) {
264	        String normalizedFirstName = normalizeForComparison(firstName);
265	        String normalizedLastName = normalizeForComparison(lastName);
266	        return (int) this.clinicService.findAllOwners().stream()
267	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
268	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
269	            .count();
270	    }
271	
272	    /**
273	     * Find the existing owners that live in the same household as the given values, i.e. those that
274	     * share both the last name and the address when each is compared case-insensitively with
275	     * collapsed whitespace.
276	     *
277	     * @param lastName the incoming owner's last name
278	     * @param address  the incoming owner's address
279	     * @return the matching existing owners (possibly empty)
280	     */
281	    private List<Owner> findHouseholdMembers(String lastName, String address) {
282	        String normalizedLastName = normalizeForComparison(lastName);
283	        String normalizedAddress = normalizeForComparison(address);
284	        return this.clinicService.findAllOwners().stream()
285	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
286	                && normalizeForComparison(existing.getAddress()).equals(normalizedAddress))
287	            .toList();
288	    }
289	
290	    /**
291	     * Generate a stable shared household identifier for the given last name and address. The value is
292	     * derived deterministically from the normalized (case-insensitive, whitespace-collapsed) last name
293	     * and address, so every owner joining the same household resolves to the same identifier. It is the
294	     * first 12 upper-case hex characters of the SHA-256 digest of {@code <lastName>|<address>}.
295	     *
296	     * @param lastName the household's last name
297	     * @param address  the household's address
298	     * @return the stable household identifier
299	     */
300	    private String generateHouseholdId(String lastName, String address) {
301	        String key = normalizeForComparison(lastName) + "|" + normalizeForComparison(address);
302	        try {
303	            byte[] digest = MessageDigest.getInstance("SHA-256")
304	                .digest(key.getBytes(StandardCharsets.UTF_8));
305	            StringBuilder sb = new StringBuilder(digest.length * 2);
306	            for (byte b : digest) {
307	                sb.append(String.format("%02x", b));
308	            }
309	            return sb.substring(0, 12).toUpperCase(Locale.ROOT);
310	        } catch (java.security.NoSuchAlgorithmException e) {
311	            throw new IllegalStateException("SHA-256 not available", e);
312	        }
313	    }
314	
315	    /**
316	     * Normalize an owner address for storage: trim and collapse every internal run of whitespace to a
317	     * single space, upper-case the result and expand common street-type abbreviations token by token
318	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value normalizes
319	     * to the empty string. The result is the canonical form that is stored, returned and used for every
320	     * address comparison (household duplicate detection and the shared household id).
321	     *
322	     * @param address the raw address, may be {@code null}
323	     * @return the normalized address
324	     */
325	    private String normalizeAddress(String address) {
326	        if (address == null) {
327	            return "";
328	        }
329	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
330	        if (collapsed.isEmpty()) {
331	            return "";
332	        }
333	        String[] tokens = collapsed.split(" ");
334	        StringBuilder sb = new StringBuilder(collapsed.length());
335	        for (int i = 0; i < tokens.length; i++) {
336	            if (i > 0) {
337	                sb.append(' ');
338	            }
339	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
340	        }
341	        return sb.toString();
342	    }
343	
344	    /**
345	     * Normalize a value for identity comparison: trim, collapse every internal run of whitespace to a
346	     * single space and lower-case the result. A {@code null} value normalizes to the empty string.
347	     *
348	     * @param value the raw value, may be {@code null}
349	     * @return the normalized value
350	     */
351	    private String normalizeForComparison(String value) {
352	        if (value == null) {
353	            return "";
354	        }
355	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
356	    }
357	
358	    /**
359	     * Normalize an optional owner email address. A blank/absent value is treated as "not provided"
360	     * and returns {@code null}. When present, the value must be a syntactically valid address; if it
361	     * is not, an {@link InvalidRequestException} is thrown (mapped to 400 Bad Request). A valid value
362	     * is returned lower-cased.
363	     *
364	     * @param email the raw email from the request payload, may be {@code null}
365	     * @return the lower-cased email, or {@code null} when none was provided
366	     */
367	    private String normalizeEmail(String email) {
368	        if (!StringUtils.hasText(email)) {
369	            return null;
370	        }
371	        if (!EMAIL_PATTERN.matcher(email).matches()) {
372	            throw new InvalidRequestException(List.of("email"));
373	        }
374	        return email.toLowerCase(Locale.ROOT);
375	    }
376	
377	    /**
378	     * Normalize a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value that
379	     * already carries a leading '+' keeps its country code; otherwise the default country code
380	     * ({@code +61}) is assumed and a single leading '0' is dropped from the national digits. The
381	     * result must be a '+' followed by 8 to 15 digits, otherwise an {@link InvalidRequestException}
382	     * is thrown (mapped to 400 Bad Request).
383	     *
384	     * @param telephone the raw telephone from the request payload
385	     * @return the E.164 string (e.g. {@code +61412345678})
386	     */
387	    private String normalizeTelephone(String telephone) {
388	        String cleaned = TELEPHONE_SEPARATORS.matcher(telephone).replaceAll("");
389	        String candidate;
390	        if (cleaned.startsWith("+")) {
391	            candidate = cleaned;
392	        } else {
393	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
394	            candidate = "+" + DEFAULT_COUNTRY_CODE + national;
395	        }
396	        if (!E164_PATTERN.matcher(candidate).matches()) {
397	            throw new InvalidRequestException(List.of("telephone"));
398	        }
399	        return candidate;
400	    }
401	
402	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
403	    @Transactional
404	    @Override
405	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
406	        Owner owner = this.clinicService.findOwnerById(ownerId);
407	        if (owner == null) {
408	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
409	        }
410	        this.clinicService.deleteOwner(owner);
411	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
412	    }
413	
414	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
415	    @Override
416	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
417	        Owner owner = this.clinicService.findOwnerById(ownerId);
418	        if (owner == null) {
419	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
420	        }
421	        HttpHeaders headers = new HttpHeaders();
422	        Pet pet = petMapper.toPet(petFieldsDto);
423	        owner.setId(ownerId);
424	        pet.setOwner(owner);
425	        pet.getType().setName(null);
426	        this.clinicService.savePet(pet);
427	        PetDto petDto = petMapper.toPetDto(pet);
428	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
429	            .buildAndExpand(pet.getId()).toUri());
430	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
431	    }
432	
433	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
434	    @Override
435	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
436	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
437	        if (currentOwner != null) {
438	            Pet currentPet = this.clinicService.findPetById(petId);
439	            if (currentPet != null) {
440	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
441	                currentPet.setName(petFieldsDto.getName());
442	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
443	                this.clinicService.savePet(currentPet);
444	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
445	            }
446	        }
447	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
448	    }
449	
450	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
451	    @Override
452	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
453	        HttpHeaders headers = new HttpHeaders();
454	        Visit visit = visitMapper.toVisit(visitFieldsDto);
455	        Pet pet = new Pet();
456	        pet.setId(petId);
457	        visit.setPet(pet);
458	        this.clinicService.saveVisit(visit);
459	        VisitDto visitDto = visitMapper.toVisitDto(visit);
460	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
461	            .buildAndExpand(visit.getId()).toUri());
462	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
463	    }
